<?php $progressActive=($filters['sort']??'')==='progress_percent';$progressDirection=$progressActive?($filters['direction']??'asc'):'asc';$progressNext=$progressActive && $progressDirection==='asc'?'desc':'asc'; ?>
<span class="list-progress-sort"><a href="<?= e(query_url('/'.$section,$baseQuery,['sort'=>'progress_percent','direction'=>$progressNext,'page'=>1])) ?>" class="<?= $progressActive?'selected':'' ?>" aria-label="<?= $progressNext==='asc'?'Trier par avancement croissant':'Trier par avancement décroissant' ?>" title="<?= e($progressActive?'Avancement '.($progressDirection==='asc'?'croissant':'décroissant').' — cliquer pour inverser':'Trier par avancement croissant') ?>" <?= $progressActive?'aria-current="true"':'' ?>><span>Avancement</span><?= icon($progressDirection==='asc'?'up':'down') ?></a></span>
